import type { Meta, StoryObj } from "@storybook/vue3";

import { delay, http, HttpResponse } from "msw";

import BaseInfoHelpListItem from "@/components/basisdaten/BaseInfoHelpListItem.vue";
import BaseInfoHelpListItemContent from "@/components/basisdaten/BaseInfoHelpListItemContent.vue";
import TheInfoHelpIcon from "@/components/basisdaten/TheInfoHelpIcon.vue";

const beispielHandbuchBlob = new Blob(
  [
    "",
  ],
  { type: "application/pdf" }
);

// TODO hier passiert noch nichts
function _triggerDownload(blob: Blob): void {
  const url = window.URL.createObjectURL(blob);
  const link = document.createElement("a");

  link.href = url;
  link.download = "beispiel.pdf";

  document.body.appendChild(link);
  link.click();
  link.remove();
  window.URL.revokeObjectURL(url);
}

const meta = {
  component: TheInfoHelpIcon,
  subcomponents: { BaseInfoHelpListItem, BaseInfoHelpListItemContent },
  decorators: [
    () => ({
      template: '<div style="background-color: #546e7a"><story/></div>',
    }),
  ],
  parameters: {
    msw: {
      handlers: [
        http.all("/api/*", async () => {
          await delay(2000);
          _triggerDownload(beispielHandbuchBlob);
          return new HttpResponse(beispielHandbuchBlob, {
            status: 200,
            headers: {
              "Content-Type": "application/pdf",
              "Content-Disposition": 'attachment; filename="beispiel.pdf"',
            },
          });
        }),
      ],
    },
  },
  args: {},
} satisfies Meta<typeof TheInfoHelpIcon>;
export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {},
};
